    result = {'ok': True, 'issues': []}
    try:
        r = subprocess.run(
            ['powershell', '-Command', 'Write-Host ps_ok'],
            capture_output=True, text=True, timeout=5,
            encoding='utf-8', errors='replace'
        )
        if r.returncode != 0:
            result['issues'].append(f'PowerShell不可用: {r.stderr[:100]}')
            result['ok'] = False
